    for n in (3, 5, 8, 12, 20, 40):
        for _ in range(2):
            p = rng.random()
            tests.append(fmt([1 if rng.random() < p else 0 for _ in range(n)]))
    N = 500000
    tests.append(fmt([rng.randint(0, 1) for _ in range(N)]))
    tests.append(fmt([1] * N))
    tests.append(fmt([1, 0] * (N // 2)))
    tests.append(fmt([1] * (N // 2) + [0] * (N // 2)))
    return tests

